#!/usr/bin/env python3
"""Deterministic dispatcher for EDARSAHUB ChatGPT-controlled worker jobs.

ChatGPT decides the exact repository changes and sends them as structured
``edarsahub.worker-job.v2`` actions. This dispatcher applies only those actions,
runs only allow-listed validations, verifies the exact changed-file scope,
creates one commit, and integrates it into ``Edarsahub_Desarrollo``.

No secondary AI executor is called. No shell command supplied by a job is ever
executed.
"""

from __future__ import annotations

# WORKER_DELIVERABLE_IMPORT_COMPAT_V1
try:
    from tools.mirror_sync.worker_deliverable_contract import evaluate_deliverables, materialize_deliverables, normalize_deliverable_specs, normalize_required_deliverables
    from tools.mirror_sync.worker_mutation_materializer import V2_ACTIONS, apply_mutation, is_v2_mutation_action
except ModuleNotFoundError:
    from worker_deliverable_contract import evaluate_deliverables, materialize_deliverables, normalize_deliverable_specs, normalize_required_deliverables
    from worker_mutation_materializer import V2_ACTIONS, apply_mutation, is_v2_mutation_action

import fcntl
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

try:
    from tools.mirror_sync.readonly_audit_profiles import build_readonly_audit_checks, is_allowed_readonly_audit_profile
except ModuleNotFoundError:
    from readonly_audit_profiles import build_readonly_audit_checks, is_allowed_readonly_audit_profile

from worker_concurrency import evaluate_scope_advance
from worker_scheduling import normalize_metadata
from worker_slot_runtime import (
    create_slot,
    heartbeat_slot,
    load_slot,
    reclaim_stale_slot,
    release_slot,
    update_slot_state,
)
from worker_slot_runtime import SlotRuntimeError
from git_divergence_guard import (GitGuardError, _expected_platform_system_deps_drift, acquire_writer_lock, compare_and_swap, inspect_repository, mutation_policy, post_push_verify, recover_authorized_local_ahead, release_writer_lock, requires_writer_lock, scoped_push_env, validate_commit_scope)

ROOT = Path(os.environ.get("EDARSAHUB_ROOT", "/app"))
STATE = ROOT / ".git" / "universal-worker-queue"
PENDING = STATE / "pending"
PROCESSING = STATE / "processing"
DONE = STATE / "done"
REJECTED = STATE / "rejected"
RESULTS = STATE / "results"
RUNTIME = STATE / "runtime"
WORKTREES = Path(os.environ.get("EDARSAHUB_JOB_WORKTREES", "/tmp/edarsahub-worker-jobs"))
LOCK_FILE = STATE / "dispatcher.lock"
PREFERRED_JOB_PATH = RUNTIME / "preferred_job.json"
REMOTE = os.environ.get("EDARSAHUB_QUEUE_REMOTE", "origin")
DEV_BRANCH = "Edarsahub_Desarrollo"
MAX_SECONDS = int(os.environ.get("EDARSAHUB_JOB_MAX_SECONDS", "1800"))
MAX_CONCURRENCY_REPLAY_ATTEMPTS = int(os.environ.get("EDARSAHUB_CONCURRENCY_REPLAY_ATTEMPTS", "3"))
JOB_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{2,120}$")
ALLOWED_ACTIONS = {"replace_text", "write_file", "delete_file", "insert_before", "insert_after", "append_once"}
ALLOWED_CHECKS = {"git_diff_check", "py_compile", "pytest", "frontend_build", "sql_readonly_audit", "repository_contract_audit", "worker_result_semantic_extract", "worker_maintenance_history_readonly", "worker_result_detail_read"}
READ_ONLY_MODE = "READ_ONLY"
READ_ONLY_CHECKS = {"git_diff_check", "py_compile", "pytest", "sql_readonly_audit", "repository_contract_audit", "worker_result_semantic_extract", "worker_maintenance_history_readonly", "worker_result_detail_read"}
SOFTRESTAURANT_FULL_HISTORY_MODE = "SOFTRESTAURANT_FULL_HISTORY_RESYNC"
MPRO_FULL_HISTORY_MODE = "MPRO_FULL_HISTORY_RESYNC"
COMERCIAL_RANGE_RESYNC_MODE = "COMERCIAL_RANGE_RESYNC"
COMERCIAL_OPEN_DAY_SYNC_MODE = "COMERCIAL_OPEN_DAY_SYNC"
COMERCIAL_RANGE_AUDIT_PROFILE = "closed_ticket_metadata"
COMERCIAL_OPEN_DAY_AUDIT_PROFILE = "open_day_ticket_metadata"
ISCAM_DETAIL_BACKFILL_MODE = "ISCAM_DETAIL_BACKFILL"
ISCAM_PAYMENTS_ONLY_RESYNC_MODE = "ISCAM_PAYMENTS_ONLY_RESYNC"
SERVER_REGISTRY_METADATA_UPDATE_MODE = "SERVER_REGISTRY_METADATA_UPDATE"
API_LOCAL_HEALTH_TEST_MODE = "API_LOCAL_HEALTH_TEST"
SQL_MIGRATION_DEVELOPMENT_MODE = "SQL_MIGRATION_DEVELOPMENT"
WORKER_SQL_BACKFILL_DEVELOPMENT_MODE = "WORKER_SQL_BACKFILL_DEVELOPMENT"
FRONTEND_BUILD_CERTIFICATION_MODE = "FRONTEND_BUILD_CERTIFICATION"
SYNC_HISTORICAL_PARENT_MODE = "SYNC_HISTORICAL_PARENT"
SYNC_HISTORICAL_ATOMIC_MODE = "SYNC_HISTORICAL_ATOMIC"
SYNC_HISTORICAL_PARENT_AUDIT_PROFILE = "sync_historical_parent_status_v1"
SYNC_HISTORICAL_ATOMIC_AUDIT_PROFILE = "sync_historical_atomic_status_v1"
UNIT_CODE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{1,31}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
SOFTRESTAURANT_RESYNC_MAX_SECONDS = int(os.environ.get("EDARSAHUB_SOFTRESTAURANT_RESYNC_MAX_SECONDS", "21600"))

RUNTIME_PYTHON = Path("/root/.venv/bin/python")


def resolve_canonical_python() -> str:
    repo_python = ROOT / ".venv" / "bin" / "python"
    repo_venv_config = ROOT / ".venv" / "pyvenv.cfg"
    if repo_venv_config.is_file() and repo_python.is_file() and os.access(repo_python, os.X_OK):
        return str(repo_python)
    if RUNTIME_PYTHON.is_file() and os.access(RUNTIME_PYTHON, os.X_OK):
        return str(RUNTIME_PYTHON)
    return sys.executable


PYTHON_BIN = resolve_canonical_python()


def load_backend_runtime_env() -> dict[str, str]:
    env_file = ROOT / "backend" / ".env"
    loaded: dict[str, str] = {}
    if not env_file.is_file():
        return loaded
    for raw_line in env_file.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export "):].lstrip()
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
            continue
        if key in os.environ:
            continue
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        loaded[key] = value
    return loaded


def now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def build_comercial_audit_checks(job: dict[str, Any]) -> list[dict[str, Any]]:
    """Materializa auditorias SQL preaprobadas sin aceptar SQL desde el job."""
    mode = str(job.get("mode") or "")
    profile = str(job.get("audit_profile") or "").strip()

    if mode == COMERCIAL_RANGE_RESYNC_MODE and profile == COMERCIAL_RANGE_AUDIT_PROFILE:
        fecha_inicio = str(job.get("fecha_inicio") or "")
        fecha_fin = str(job.get("fecha_fin") or "")
        units = [
            str(unit).strip().upper()
            for unit in (job.get("units") or [])
            if str(unit).strip()
        ]
        quoted_units = ",".join("'" + unit.replace("'", "''") + "'" for unit in units)
        return [{
            "type": "sql_readonly_audit",
            "source": "EDARSAHUB",
            "queries": [{
                "name": "closed_ticket_metadata_post_backfill",
                "sql": (
                    "SELECT unidad_negocio_id, COUNT(*) AS lineas, "
                    "COUNT(partida_origen_id) AS con_partida_origen, "
                    "COUNT(ticket_fecha) AS con_ticket_fecha, "
                    "COUNT(cliente_id) AS con_cliente_id, "
                    "COUNT(cliente_rfc) AS con_cliente_rfc, "
                    "COUNT(precio_unitario) AS con_precio_unitario, "
                    "COUNT(importe_bruto) AS con_importe_bruto "
                    "FROM dbo.Comercial_Inteligencia_VentasDetalleProducto "
                    f"WHERE fecha_operacion>='{fecha_inicio}' "
                    f"AND fecha_operacion<='{fecha_fin}' "
                    f"AND unidad_negocio_id IN ({quoted_units}) "
                    "AND ISNULL(activo,1)=1 "
                    "GROUP BY unidad_negocio_id ORDER BY unidad_negocio_id"
                ),
            }],
        }]

    if mode == COMERCIAL_OPEN_DAY_SYNC_MODE and profile == COMERCIAL_OPEN_DAY_AUDIT_PROFILE:
        fecha_operacion = str(job.get("fecha_operacion") or "")
        return [{
            "type": "sql_readonly_audit",
            "source": "EDARSAHUB",
            "queries": [{
                "name": "ticket_open_day_metadata_latest",
                "sql": (
                    "WITH x AS ("
                    "SELECT unidad_negocio_id,sucursal_id,fecha_operacion,"
                    "snapshot_timestamp,ventas_abiertas,ventas_cerradas_dia,"
                    "detalle_abiertas_json,"
                    "ROW_NUMBER() OVER(PARTITION BY unidad_negocio_id "
                    "ORDER BY snapshot_timestamp DESC) AS rn "
                    "FROM dbo.Comercial_Ventas_Dia_Abiertas_v2 "
                    f"WHERE fecha_operacion='{fecha_operacion}') "
                    "SELECT unidad_negocio_id,sucursal_id,fecha_operacion,"
                    "snapshot_timestamp,ventas_abiertas,ventas_cerradas_dia,"
                    "CASE WHEN ISJSON(detalle_abiertas_json)=1 THEN 1 ELSE 0 END AS json_valido,"
                    "CASE WHEN ISJSON(detalle_abiertas_json)=1 "
                    "THEN (SELECT COUNT(*) FROM OPENJSON(detalle_abiertas_json)) ELSE -1 END AS detalle_filas,"
                    "CASE WHEN detalle_abiertas_json LIKE '%\"partida_origen_id\"%' THEN 1 ELSE 0 END AS tiene_partida_origen,"
                    "CASE WHEN detalle_abiertas_json LIKE '%\"cliente_id\"%' THEN 1 ELSE 0 END AS tiene_cliente_id,"
                    "CASE WHEN detalle_abiertas_json LIKE '%\"cliente_rfc\"%' THEN 1 ELSE 0 END AS tiene_cliente_rfc,"
                    "CASE WHEN detalle_abiertas_json LIKE '%\"precio_unitario\"%' THEN 1 ELSE 0 END AS tiene_precio_unitario,"
                    "CASE WHEN detalle_abiertas_json LIKE '%\"importe_bruto\"%' THEN 1 ELSE 0 END AS tiene_importe_bruto "
                    "FROM x WHERE rn=1 ORDER BY unidad_negocio_id"
                ),
            }],
        }]

    if mode == SYNC_HISTORICAL_PARENT_MODE and profile == SYNC_HISTORICAL_PARENT_AUDIT_PROFILE:
        parent_id = int(job.get("parent_sync_control_id") or 0)
        return [{
            "type": "sql_readonly_audit",
            "source": "EDARSAHUB",
            "queries": [{
                "name": "sync_historical_parent_post_status",
                "sql": (
                    "SELECT p.SyncControlID,p.Status,p.CorrelationID,"
                    "COUNT(c.SyncControlID) AS total_hijos,"
                    "SUM(CASE WHEN c.Status='SUCCESS' THEN 1 ELSE 0 END) AS exitosos,"
                    "SUM(CASE WHEN c.Status='PERMANENT_FAILURE' THEN 1 ELSE 0 END) AS fallos_permanentes,"
                    "SUM(CASE WHEN c.Status='CANCELLED_SAFE' THEN 1 ELSE 0 END) AS cancelados "
                    "FROM dbo.Sync_Control_Ejecuciones p "
                    "LEFT JOIN dbo.Sync_Control_Ejecuciones c "
                    "ON c.ParentSyncControlID=p.SyncControlID AND c.RunKind='ATOMIC' "
                    f"WHERE p.SyncControlID={parent_id} AND p.RunKind='PARENT' "
                    "GROUP BY p.SyncControlID,p.Status,p.CorrelationID"
                ),
            }],
        }]

    if mode == SYNC_HISTORICAL_ATOMIC_MODE and profile == SYNC_HISTORICAL_ATOMIC_AUDIT_PROFILE:
        control_id = int(job.get("sync_control_id") or 0)
        return [{
            "type": "sql_readonly_audit",
            "source": "EDARSAHUB",
            "queries": [{
                "name": "sync_historical_atomic_post_status",
                "sql": (
                    "SELECT SyncControlID,ParentSyncControlID,Status,CodigoSync,"
                    "UnidadNegocioID,ConexionID,AttemptCount,MaxAttempts,"
                    "RegistrosProcesados,RegistrosInsertados,RegistrosActualizados,RegistrosError "
                    "FROM dbo.Sync_Control_Ejecuciones "
                    f"WHERE SyncControlID={control_id} AND RunKind='ATOMIC'"
                ),
            }],
        }]

    return []


def summarize_softrestaurant_output(output: str) -> dict[str, Any]:
    summary: dict[str, Any] = {"results": []}
    for raw_line in reversed((output or "").splitlines()):
        try:
            payload = json.loads(raw_line)
        except Exception:
            continue
        if not isinstance(payload, dict) or payload.get("event") != "summary":
            continue
        rows = payload.get("results") or []
        if not isinstance(rows, list):
            return summary
        sanitized = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            error_domains = []
            error_types = []
            errors = row.get("errors") or []
            if isinstance(errors, list):
                for error in errors:
                    if isinstance(error, dict):
                        domain = str(error.get("domain") or "").strip()
                        if domain:
                            error_domains.append(domain)
                        value = error.get("error")
                        error_types.append(type(value).__name__)
                    elif isinstance(error, str):
                        error_types.append(error.split(":", 1)[0][:80])
            sanitized.append({
                "unidad": str(row.get("unidad") or ""),
                "status": str(row.get("status") or ""),
                "payment_windows": int(row.get("payment_windows") or 0),
                "corte_windows": int(row.get("corte_windows") or 0),
                "pagos_insertados": int(row.get("pagos_insertados") or 0),
                "error_domains": sorted(set(error_domains)),
                "error_types": sorted(set(error_types)),
            })
        return {"results": sanitized}
    return summary


def summarize_iscam_detail_backfill_output(output: str) -> dict[str, Any]:
    summary: dict[str, Any] = {"unidades": []}
    for raw_line in reversed((output or "").splitlines()):
        try:
            payload = json.loads(raw_line)
        except Exception:
            continue
        if not isinstance(payload, dict) or not isinstance(payload.get("unidades"), list):
            continue
        units = []
        for unit in payload.get("unidades") or []:
            if not isinstance(unit, dict):
                continue
            days = []
            for day in unit.get("dias") or []:
                if not isinstance(day, dict):
                    continue
                days.append({
                    key: day.get(key)
                    for key in (
                        "fecha_operacion", "status",
                        "ventas_runtime", "ventas_pos", "delta_ventas",
                        "tickets_runtime", "tickets_pos", "delta_tickets",
                        "pax_runtime", "pax_pos", "delta_pax",
                        "filas_insertadas", "error_type", "error_code",
                    )
                    if key in day
                })
            units.append({
                "unidad": str(unit.get("unidad") or ""),
                "ya_ok": int(unit.get("ya_ok") or 0),
                "candidatos": int(unit.get("candidatos") or 0),
                "reparables": int(unit.get("reparables") or 0),
                "bloqueados": int(unit.get("bloqueados") or 0),
                "sin_runtime": int(unit.get("sin_runtime") or 0),
                "filas_insertadas": int(unit.get("filas_insertadas") or 0),
                "dias": days,
            })
        return {
            "modo": str(payload.get("modo") or ""),
            "fecha_inicio": str(payload.get("fecha_inicio") or ""),
            "fecha_fin_exclusivo": str(payload.get("fecha_fin_exclusivo") or ""),
            "dias_evaluados": int(payload.get("dias_evaluados") or 0),
            "dias_ya_ok": int(payload.get("dias_ya_ok") or 0),
            "dias_candidatos": int(payload.get("dias_candidatos") or 0),
            "dias_reparables": int(payload.get("dias_reparables") or 0),
            "dias_bloqueados": int(payload.get("dias_bloqueados") or 0),
            "dias_sin_runtime": int(payload.get("dias_sin_runtime") or 0),
            "filas_insertadas": int(payload.get("filas_insertadas") or 0),
            "unidades": units,
        }
    return summary


def run(args: list[str], cwd: Path | None = None, check: bool = False, timeout: int | None = None, env_extra: dict[str, str] | None = None):
    env = {**os.environ, "GIT_TERMINAL_PROMPT": "0"}
    if env_extra:
        env.update(env_extra)
    return subprocess.run(args, cwd=str(cwd or ROOT), text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=check, timeout=timeout, env=env)


def git(*args: str, cwd: Path | None = None, check: bool = True):
    result = run(["git", *args], cwd=cwd, check=False)
    if check and result.returncode != 0:
        raise RuntimeError(f"GIT_FAILED:{' '.join(args)}:{result.stdout[-2000:]}")
    return result


def git_changed_paths(base_sha: str, head_sha: str) -> list[str]:
    result = git("diff", "--name-only", base_sha, head_sha, "--")
    return sorted({line.strip() for line in result.stdout.splitlines() if line.strip()})


def git_is_ancestor(base_sha: str, head_sha: str) -> bool:
    return git("merge-base", "--is-ancestor", base_sha, head_sha, check=False).returncode == 0


def resolve_repository_credential_helper() -> str:
    result = git("config", "--local", "--get", "credential.helper", cwd=ROOT, check=False)
    return result.stdout.strip() if result.returncode == 0 else ""


def ensure_dirs() -> None:
    for path in (PENDING, PROCESSING, DONE, REJECTED, RESULTS, WORKTREES):
        path.mkdir(parents=True, exist_ok=True)
    LOCK_FILE.parent.mkdir(parents=True, exist_ok=True)


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=path.parent, delete=False) as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")
        temp_name = handle.name
    os.replace(temp_name, path)


def load_envelope(path: Path) -> dict[str, Any]:
    with path.open("r", encoding="utf-8") as handle:
        data = json.load(handle)
    if not isinstance(data, dict) or not isinstance(data.get("job"), dict):
        raise ValueError("INVALID_PENDING_ENVELOPE")
    return data


def safe_path(worktree: Path, relative: str) -> Path:
    rel = Path(relative)
    if rel.is_absolute() or ".." in rel.parts or (rel.parts and rel.parts[0] == ".git"):
        raise ValueError(f"UNSAFE_PATH:{relative}")
    target = (worktree / rel).resolve()
    root = worktree.resolve()
    if target != root and root not in target.parents:
        raise ValueError(f"PATH_ESCAPES_WORKTREE:{relative}")
    return target


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def verify_expected_hash(path: Path, action: dict[str, Any]) -> None:
    expected = action.get("expected_sha256")
    if expected is None:
        return
    if not path.is_file():
        raise RuntimeError(f"EXPECTED_FILE_MISSING:{action['path']}")
    actual = sha256_file(path)
    if actual != expected:
        raise RuntimeError(f"EXPECTED_SHA256_MISMATCH:{action['path']}:{actual}")


def _cleanup_residual_worker_worktree(path: Path, branch: str) -> None:
    # Remove stale worktree registrations before deleting the per-job branch.
    # This is intentionally scoped to the exact deterministic branch/path of
    # the current job and never touches unrelated worktrees.
    git("worktree", "prune", check=False)

    if path.exists():
        status = git(
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
            cwd=path,
            check=False,
        )
        if status.returncode == 0 and status.stdout.strip():
            raise RuntimeError(
                f"AGENT_GUARD_RESIDUAL_WORKTREE_DIRTY:{path}"
            )
        git("worktree", "remove", "--force", str(path), check=False)
        shutil.rmtree(path, ignore_errors=True)

    git("worktree", "prune", check=False)
    deleted = git("branch", "-D", branch, check=False)

    still_exists = git(
        "show-ref",
        "--verify",
        "--quiet",
        f"refs/heads/{branch}",
        check=False,
    )
    if still_exists.returncode == 0:
        detail = (deleted.stdout or "")[-1200:]
        raise RuntimeError(
            "AGENT_GUARD_RESIDUAL_BRANCH_BUSY:"
            + branch
            + ":"
            + detail
        )


def prepare_worktree(job_id: str, base_sha: str, allowed_paths: list[str]) -> tuple[Path, str]:
    safe_id = re.sub(r"[^A-Za-z0-9._-]", "-", job_id)
    branch = f"agent/worker/{safe_id}"
    path = WORKTREES / safe_id
    agent_id = f"worker-{safe_id}"

    _cleanup_residual_worker_worktree(path, branch)

    git("branch", branch, base_sha)
    guard = ROOT / ".git" / "agent-guard" / "bin" / "agent_guard.py"
    if not guard.is_file():
        git("branch", "-D", branch, check=False)
        raise RuntimeError("AGENT_GUARD_NOT_FOUND")
    if not allowed_paths:
        git("branch", "-D", branch, check=False)
        raise RuntimeError("AGENT_GUARD_PATHS_REQUIRED")
    command = [PYTHON_BIN, str(guard), "worktree-create", "--agent-id", agent_id, "--task-id", safe_id, "--description", f"ChatGPT deterministic worker job {job_id}", "--domain", f"worker_job_{safe_id}", "--branch", branch, "--directory", str(path)]
    for allowed_path in allowed_paths:
        command.extend(["--path", allowed_path])
    created = run(command, cwd=ROOT)
    if created.returncode != 0:
        # A failed Agent Guard worktree creation must not poison the next retry
        # with a checked-out branch or stale worktree registration.
        git("worktree", "remove", "--force", str(path), check=False)
        shutil.rmtree(path, ignore_errors=True)
        git("worktree", "prune", check=False)
        git("branch", "-D", branch, check=False)
        raise RuntimeError(f"AGENT_GUARD_WORKTREE_CREATE_FAILED:{created.stdout[-2000:]}")
    if not path.is_dir():
        git("worktree", "prune", check=False)
        git("branch", "-D", branch, check=False)
        raise RuntimeError("AGENT_GUARD_WORKTREE_NOT_CREATED")
    head = git("rev-parse", "HEAD", cwd=path).stdout.strip()
    if head != base_sha:
        git("worktree", "remove", "--force", str(path), check=False)
        shutil.rmtree(path, ignore_errors=True)
        git("worktree", "prune", check=False)
        git("branch", "-D", branch, check=False)
        raise RuntimeError(f"WORKTREE_BASE_MISMATCH:expected={base_sha}:actual={head}")
    return path, branch


def apply_action(worktree: Path, action: dict[str, Any]) -> str:
    kind = str(action.get("type"))
    if kind not in ALLOWED_ACTIONS:
        raise ValueError(f"UNSUPPORTED_ACTION:{kind}")
    relative = str(action.get("path") or "")
    target = safe_path(worktree, relative)
    repo_path = Path(relative)
    if (
        kind == "write_file"
        and repo_path.parts[:2] == ("backend", "core")
        and not target.exists()
    ):
        raise RuntimeError(f"CORE_GROWTH_FORBIDDEN:{relative}")
    is_v2 = is_v2_mutation_action(action)

    if is_v2:
        evidence = apply_mutation(target, action)
        return {
            "path": relative,
            **evidence,
        }

    verify_expected_hash(target, action)
    if kind == "replace_text":
        if not target.is_file():
            raise RuntimeError(f"REPLACE_TARGET_MISSING:{relative}")
        old = action["old"]
        new = action["new"]
        expected_count = int(action.get("expected_count", 1))
        text = target.read_text(encoding="utf-8")
        actual_count = text.count(old)
        if actual_count != expected_count:
            raise RuntimeError(f"REPLACE_COUNT_MISMATCH:{relative}:expected={expected_count}:actual={actual_count}")
        target.write_text(text.replace(old, new), encoding="utf-8")
        return relative
    if kind == "write_file":
        content = action["content"]
        if target.exists():
            if "expected_sha256" not in action:
                raise RuntimeError(f"WRITE_EXISTING_REQUIRES_EXPECTED_SHA256:{relative}")
            current_size = target.stat().st_size
            new_size = len(content.encode("utf-8"))
            if current_size >= 4096 and new_size < int(current_size * 0.75):
                raise RuntimeError(f"WRITE_FILE_LARGE_SHRINK_BLOCKED:{relative}:current={current_size}:new={new_size}")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        return relative
    if kind == "delete_file":
        if not target.is_file():
            raise RuntimeError(f"DELETE_TARGET_MISSING:{relative}")
        target.unlink()
        return relative
    raise ValueError(f"UNSUPPORTED_ACTION:{kind}")


def heartbeat_active_slot() -> bool:
    """Refresh canonical ownership while a long validation is running."""
    current_job_path = RUNTIME / "current_job_id"

    try:
        current_job_id = current_job_path.read_text(
            encoding="utf-8"
        ).strip()
    except OSError:
        return False

    if not current_job_id:
        return False

    for slot_id in ("readonly-1", "mutation-1"):
        try:
            slot = load_slot(slot_id)
        except SlotRuntimeError:
            continue

        if not isinstance(slot, dict):
            continue

        if str(slot.get("job_id") or "").strip() != current_job_id:
            continue

        if str(slot.get("state") or "").strip() not in {
            "CLAIMED",
            "RUNNING",
            "TERMINALIZING",
        }:
            continue

        heartbeat_slot(
            slot_id,
            execution_pid=os.getpid(),
        )
        return True

    return False


def run_check_process(
    args: list[str],
    *,
    cwd: Path,
    timeout: int,
    env_extra: dict[str, str] | None = None,
    clean_env: bool = False,
    preexec_fn: Any = None,
):
    """Run one validation while keeping slot ownership fresh."""
    if clean_env:
        env = dict(env_extra or {})
        env.setdefault("GIT_TERMINAL_PROMPT", "0")
    else:
        env = {
            **os.environ,
            "GIT_TERMINAL_PROMPT": "0",
        }
        if env_extra:
            env.update(env_extra)

    effective_timeout = max(1, int(timeout))
    deadline = time.monotonic() + effective_timeout

    with tempfile.TemporaryFile(
        mode="w+",
        encoding="utf-8",
    ) as output:
        popen_kwargs: dict[str, Any] = {
            "cwd": str(cwd),
            "text": True,
            "stdout": output,
            "stderr": subprocess.STDOUT,
            "env": env,
        }
        if preexec_fn is not None:
            popen_kwargs["preexec_fn"] = preexec_fn
        proc = subprocess.Popen(args, **popen_kwargs)

        while True:
            heartbeat_active_slot()

            remaining = deadline - time.monotonic()

            if remaining <= 0:
                proc.kill()
                proc.wait()
                output.seek(0)
                captured = output.read()
                raise subprocess.TimeoutExpired(
                    args,
                    effective_timeout,
                    output=captured,
                )

            try:
                returncode = proc.wait(
                    timeout=min(20.0, remaining)
                )
                break
            except subprocess.TimeoutExpired:
                continue

        heartbeat_active_slot()
        output.seek(0)

        return subprocess.CompletedProcess(
            args=args,
            returncode=returncode,
            stdout=output.read(),
        )


def run_check(worktree: Path, check: dict[str, Any], readonly: bool = False, base_sha: str | None = None) -> dict[str, Any]:
    kind = str(check.get("type"))
    started = now()
    env_extra: dict[str, str] = {}
    clean_env = False
    check_timeout = MAX_SECONDS
    preexec_fn: Any = None
    hermetic_tmpdir: tempfile.TemporaryDirectory[str] | None = None
    isolation_profile: str | None = None
    if kind == "git_diff_check":
        cmd = (
            ["git", "diff", "--check", base_sha, "HEAD"]
            if base_sha
            else ["git", "diff", "--check"]
        )
        cwd = worktree
    elif kind == "py_compile":
        paths = [str(p) for p in check.get("paths") or []]
        cmd = [PYTHON_BIN, "-m", "py_compile", *paths]
        cwd = worktree
        if readonly:
            env_extra["PYTHONPYCACHEPREFIX"] = str(Path(tempfile.gettempdir()) / "edarsahub-worker-readonly-pyc")
    elif kind == "pytest":
        backend = worktree / "backend"
        if not backend.is_dir():
            raise RuntimeError("PYTEST_BACKEND_NOT_FOUND")
        paths = []
        for raw_path in check.get("paths") or []:
            path = str(raw_path)
            if path == "backend":
                path = "."
            elif path.startswith("backend/"):
                path = path[len("backend/"):]
            paths.append(path)
        hermetic = str(check.get("isolation") or "").strip().upper() == "HERMETIC_READONLY"
        pytest_args = ["-q"]
        if readonly or hermetic:
            pytest_args.extend(["-p", "no:cacheprovider"])
        cwd = backend
        python_path = os.pathsep.join(
            (
                str(backend),
                str(worktree),
            )
        )
        if hermetic:
            try:
                from tools.mirror_sync.hermetic_pytest_plugin import (
                    HERMETIC_ISOLATION_PROFILE,
                    HERMETIC_PYTEST_MAX_SECONDS,
                    build_hermetic_pytest_env,
                    make_hermetic_preexec_fn,
                )
            except ModuleNotFoundError:
                from hermetic_pytest_plugin import (
                    HERMETIC_ISOLATION_PROFILE,
                    HERMETIC_PYTEST_MAX_SECONDS,
                    build_hermetic_pytest_env,
                    make_hermetic_preexec_fn,
                )
            pytest_args.extend(["-p", "tools.mirror_sync.hermetic_pytest_plugin"])
            hermetic_tmpdir = tempfile.TemporaryDirectory(prefix="edarsahub-hermetic-pytest-")
            env_extra = build_hermetic_pytest_env(
                pythonpath=python_path,
                tmpdir=hermetic_tmpdir.name,
                path_env=os.environ.get("PATH", ""),
            )
            clean_env = True
            check_timeout = min(MAX_SECONDS, HERMETIC_PYTEST_MAX_SECONDS)
            preexec_fn = make_hermetic_preexec_fn(check_timeout)
            isolation_profile = HERMETIC_ISOLATION_PROFILE
        else:
            env_extra = {
                **load_backend_runtime_env(),
                "PYTHONPATH": python_path,
            }
            if readonly:
                env_extra["PYTHONDONTWRITEBYTECODE"] = "1"
        cmd = [PYTHON_BIN, "-m", "pytest", *pytest_args, *paths]
    elif kind == "repository_contract_audit":
        helper = worktree / "tools" / "mirror_sync" / "repository_contract_audit.py"
        if not helper.is_file():
            helper = ROOT / "tools" / "mirror_sync" / "repository_contract_audit.py"
        cmd = [PYTHON_BIN, str(helper), "--request-json", json.dumps(check.get("request") or {}, ensure_ascii=False)]
        cwd = worktree
        env_extra = {"PYTHONDONTWRITEBYTECODE": "1"}
    elif kind == "worker_maintenance_history_readonly":
        # Local Git common-dir Maintenance history; only the canonical Worker
        # host can access it. The only optional selector is a validated
        # source_job_id; arbitrary paths and commands remain impossible.
        helper = worktree / "tools" / "mirror_sync" / "worker_maintenance_history_readonly.py"
        if not helper.is_file():
            raise RuntimeError("G4_HISTORY_HELPER_UNAVAILABLE")
        cmd = [PYTHON_BIN, str(helper)]
        request = check.get("request") or {}
        source_job_id = str(
            request.get("source_job_id") or ""
        ).strip()
        if source_job_id:
            cmd.extend(["--source-job-id", source_job_id])
        cwd = worktree
        env_extra = {"PYTHONDONTWRITEBYTECODE": "1"}
    elif kind == "worker_result_detail_read":
        helper = (
            worktree
            / "tools"
            / "mirror_sync"
            / "worker_result_detail_read.py"
        )
        if not helper.is_file():
            helper = (
                ROOT
                / "tools"
                / "mirror_sync"
                / "worker_result_detail_read.py"
            )
        request = check.get("request") or {}
        cmd = [
            PYTHON_BIN,
            str(helper),
            "--job-id",
            str(request.get("job_id") or ""),
        ]
        cwd = worktree
        env_extra = {
            "PYTHONDONTWRITEBYTECODE": "1",
            "PYTHONPATH": str(ROOT),
        }
    elif kind == "worker_result_semantic_extract":
        helper = worktree / "tools" / "mirror_sync" / "worker_result_semantic_extract.py"
        if not helper.is_file():
            helper = ROOT / "tools" / "mirror_sync" / "worker_result_semantic_extract.py"
        cmd = [PYTHON_BIN, str(helper), "--request-json", json.dumps(check.get("request") or {}, ensure_ascii=False)]
        cwd = worktree
        env_extra = {"PYTHONDONTWRITEBYTECODE": "1"}
    elif kind == "sql_readonly_audit":
        helper = worktree / "tools" / "mirror_sync" / "sql_readonly_audit.py"
        if not helper.is_file():
            helper = ROOT / "tools" / "mirror_sync" / "sql_readonly_audit.py"
        backend = worktree / "backend"
        if not backend.is_dir():
            backend = ROOT / "backend"
        cmd = [PYTHON_BIN, str(helper), "--queries-json", json.dumps(check.get("queries") or [], ensure_ascii=False)]
        source = str(check.get("source") or "EDARSAHUB").strip().upper()
        cmd.extend(["--source", source])
        if check.get("units") is not None:
            cmd.extend(["--units-json", json.dumps(check.get("units"), ensure_ascii=False)])
        if check.get("system_types") is not None:
            cmd.extend(["--system-types-json", json.dumps(check.get("system_types"), ensure_ascii=False)])
        if check.get("server_id") is not None:
            cmd.extend(["--server-id", str(check.get("server_id"))])
        if check.get("include_inactive") is True:
            cmd.append("--include-inactive")
        cwd = worktree
        env_extra = {**load_backend_runtime_env(), "PYTHONPATH": str(backend)}
    elif kind == "frontend_build":
        directory = safe_path(worktree, str(check.get("directory", "frontend")))
        canonical_node_modules = ROOT / "frontend" / "node_modules"
        canonical_bin = canonical_node_modules / ".bin"
        env_extra = {}
        if canonical_node_modules.is_dir():
            env_extra["NODE_PATH"] = str(canonical_node_modules)
        if canonical_bin.is_dir():
            current_path = os.environ.get("PATH", "")
            env_extra["PATH"] = f"{canonical_bin}:{current_path}" if current_path else str(canonical_bin)
        cmd = ["yarn", "build"]
        cwd = directory
    else:
        raise ValueError(f"UNSUPPORTED_CHECK:{kind}")
    try:
        proc_kwargs: dict[str, Any] = {
            "cwd": cwd,
            "timeout": check_timeout,
            "env_extra": env_extra or None,
        }
        if clean_env:
            proc_kwargs["clean_env"] = True
        if preexec_fn is not None:
            proc_kwargs["preexec_fn"] = preexec_fn
        result = run_check_process(cmd, **proc_kwargs)
        full_output = result.stdout or ""
        response = {"type": kind, "status": "PASS" if result.returncode == 0 else "FAIL", "returncode": result.returncode, "started_at_utc": started, "completed_at_utc": now(), "output": full_output[-12000:]}
        if isolation_profile is not None:
            response["isolation"] = isolation_profile
        if kind in {"sql_readonly_audit", "repository_contract_audit", "worker_result_semantic_extract", "worker_maintenance_history_readonly", "worker_result_detail_read"}:
            try:
                structured_evidence = json.loads(full_output.strip())
            except (json.JSONDecodeError, TypeError):
                structured_evidence = None
            if isinstance(structured_evidence, dict):
                if kind == "sql_readonly_audit":
                    response["sql_evidence"] = structured_evidence
                elif kind == "repository_contract_audit":
                    response["repository_evidence"] = structured_evidence
                elif kind == "worker_maintenance_history_readonly":
                    response["maintenance_history_evidence"] = structured_evidence
                elif kind == "worker_result_detail_read":
                    response["result_detail_evidence"] = structured_evidence
                else:
                    response["semantic_evidence"] = structured_evidence
        return response
    except subprocess.TimeoutExpired as exc:
        text = exc.stdout if isinstance(exc.stdout, str) else ""
        timeout_resp = {"type": kind, "status": "FAIL", "returncode": 124, "started_at_utc": started, "completed_at_utc": now(), "output": f"TIMEOUT\n{text[-8000:]}"}
        if isolation_profile is not None:
            timeout_resp["isolation"] = isolation_profile
        return timeout_resp
    finally:
        if hermetic_tmpdir is not None:
            hermetic_tmpdir.cleanup()


def changed_files(worktree: Path, base_sha: str) -> list[str]:
    result = git("diff", "--name-only", base_sha, "--", cwd=worktree)
    staged_or_untracked = git("status", "--porcelain=v1", "--untracked-files=all", cwd=worktree).stdout.splitlines()
    names = {line.strip() for line in result.stdout.splitlines() if line.strip()}
    for line in staged_or_untracked:
        if len(line) >= 4:
            name = line[3:]
            if " -> " in name:
                name = name.split(" -> ", 1)[1]
            names.add(name)
    return sorted(names)


def validate_scope(worktree: Path, base_sha: str, allowed: set[str]) -> list[str]:
    actual = set(changed_files(worktree, base_sha)); extra = sorted(actual - allowed); missing = sorted(allowed - actual); blockers: list[str] = []
    if extra or missing: blockers.append("GIT_SCOPE_VIOLATION:extra=" + ",".join(extra) + ";missing=" + ",".join(missing))
    return blockers


def create_commit(worktree: Path, job_id: str, files: list[str]) -> str:
    git("add", "--", *files, cwd=worktree)
    staged = git("diff", "--cached", "--name-only", cwd=worktree).stdout.splitlines()
    if sorted(staged) != sorted(files):
        raise RuntimeError("STAGED_SCOPE_MISMATCH")
    message = f"worker({job_id}): apply ChatGPT deterministic changes"
    git("-c", "user.name=EDARSAHUB Worker", "-c", "user.email=worker@edarsahub.local", "commit", "-m", message, cwd=worktree)
    return git("rev-parse", "HEAD", cwd=worktree).stdout.strip()


def integrate(worktree: Path, branch: str, head: str, base_sha: str, write_scope: set[str], job_id: str, remote_at_start: str) -> tuple[bool, str, str, list[dict[str, Any]]]:
    candidate=head; evidence=[]; credential_helper=resolve_repository_credential_helper()
    if not credential_helper: return False,"GIT_PUSH_FAILED:credential_helper_missing",candidate,evidence
    step={"candidate_base_sha":base_sha,"candidate_sha_before":candidate,"remote_at_start":remote_at_start,"push_attempted":False}
    try: remote_dev=compare_and_swap(ROOT,remote_at_start)
    except GitGuardError as exc:
        step["decision"]=exc.code; step.update(exc.evidence); evidence.append(step); return False,exc.code,candidate,evidence
    step["remote_before_push"]=remote_dev
    if remote_dev != base_sha: step["decision"]="GIT_DIVERGENCE_BLOCKED"; evidence.append(step); return False,"GIT_DIVERGENCE_BLOCKED:base_no_longer_remote_tip",candidate,evidence
    merge_base=git("merge-base",remote_dev,candidate,check=False).stdout.strip(); step["merge_base_before_push"]=merge_base
    if merge_base != remote_dev: step["decision"]="GIT_DIVERGENCE_BLOCKED"; evidence.append(step); return False,"GIT_DIVERGENCE_BLOCKED:candidate_not_fast_forward",candidate,evidence
    try: validate_commit_scope(worktree,base_sha,candidate,write_scope)
    except GitGuardError as exc:
        step["decision"]=exc.code; step["scope_evidence"]=exc.evidence; evidence.append(step); return False,exc.code,candidate,evidence
    guard=ROOT/"scripts"/"agent_guardrails"/"validate_repository_artifacts.py"
    if guard.is_file():
        check=run([PYTHON_BIN,str(guard),"--range",base_sha,candidate],cwd=ROOT)
        if check.returncode != 0: step["artifact_guard"]="FAIL"; step["artifact_guard_output"]=check.stdout[-1000:]; evidence.append(step); return False,"GIT_SCOPE_VIOLATION:repository_artifact_guard_failed",candidate,evidence
        step["artifact_guard"]="PASS"
    push_env=scoped_push_env(job_id,"universal-worker",os.environ); push=run(["git","-c","credential.helper=","-c",f"credential.helper={credential_helper}","push",REMOTE,f"{candidate}:refs/heads/{DEV_BRANCH}"],cwd=ROOT,env_extra={k:push_env[k] for k in ("EDARSA_ALLOW_PUSH","EDARSA_PUSH_JOB_ID","EDARSA_PUSH_OWNER")})
    step["push_attempted"]=True; step["push_returncode"]=push.returncode; step["push_result"]="PASS" if push.returncode==0 else "FAIL"
    if push.returncode != 0: step["push_output"]=(push.stdout or "")[-1000:]; step["decision"]="GIT_PUSH_FAILED"; evidence.append(step); return False,"GIT_PUSH_FAILED",candidate,evidence
    try: post=post_push_verify(worktree,candidate)
    except GitGuardError as exc:
        step["decision"]=exc.code; step.update(exc.evidence); evidence.append(step); return False,exc.code,candidate,evidence
    step.update(post); step["decision"]="CERTIFIED_GIT_SYNC"; evidence.append(step); return True,candidate,candidate,evidence


def release_agent_guard_claim(job_id: str) -> tuple[bool, str]:
    safe_id = re.sub(r"[^A-Za-z0-9._-]", "-", job_id)
    agent_id = f"worker-{safe_id}"
    guard = ROOT / ".git" / "agent-guard" / "bin" / "agent_guard.py"
    if not guard.is_file():
        return False, "AGENT_GUARD_NOT_FOUND"
    released = run([PYTHON_BIN, str(guard), "release", "--agent-id", agent_id], cwd=ROOT)
    if released.returncode != 0:
        detail = released.stdout[-1000:]
        if "Claim no encontrado" in detail or "claim not found" in detail.lower():
            return True, "ALREADY_RELEASED"
        return False, detail
    return True, released.stdout[-1000:]



def _effective_readonly_tracked_status(repo: Path, raw_status: str) -> str:
    lines = raw_status.splitlines()
    if _expected_platform_system_deps_drift(repo):
        lines = [line for line in lines if line != " M .emergent/system_deps.txt"]
    return "\n".join(lines).strip()


def _native_decision_contract_required(job):
    expected = job.get("expected_native_decision")
    return isinstance(expected, dict) and bool(expected)


def _semantic_extract_payload(check_result):
    for key in (
        "semantic_evidence",
        "worker_result_semantic_extract",
        "repository_evidence",
    ):
        value = check_result.get(key)
        if isinstance(value, dict):
            return value

    output = check_result.get("output")
    if isinstance(output, str) and output.strip():
        try:
            decoded = json.loads(output)
        except json.JSONDecodeError:
            return None
        if isinstance(decoded, dict):
            return decoded
    return None



def _native_decision_from_repository_contract_audit(result, check_results):
    repository_reports = []

    for check_result in check_results:
        if (
            check_result.get("type") == "repository_contract_audit"
            and check_result.get("status") == "PASS"
        ):
            evidence = check_result.get("repository_evidence")
            if not isinstance(evidence, dict):
                output = check_result.get("output")
                if isinstance(output, str) and output.strip():
                    try:
                        decoded = json.loads(output)
                    except json.JSONDecodeError:
                        decoded = None
                    if isinstance(decoded, dict):
                        evidence = decoded
            if isinstance(evidence, dict):
                repository_reports.append(evidence)

    if not repository_reports:
        return None

    matched_terms = set()
    matched_paths = []
    scanned_files = 0
    matched_files = 0

    for report in repository_reports:
        summary = report.get("summary")
        if isinstance(summary, dict):
            scanned_files += int(summary.get("scanned_files") or 0)
            matched_files += int(summary.get("matched_files") or 0)

        evidence_items = report.get("evidence")
        if not isinstance(evidence_items, list):
            continue

        for item in evidence_items:
            if not isinstance(item, dict):
                continue

            path = item.get("path")
            if isinstance(path, str) and path:
                matched_paths.append(path)

            for term in item.get("matched_terms") or []:
                if isinstance(term, str) and term:
                    matched_terms.add(term)

    gate_label = "GATE3" if "GATE3" in str(result.get("job_id", "")).upper() else "GATE"

    return {
        "gate3_allowed": False,
        "last_gate_executed": result.get("job_id"),
        "last_gate_certified": False,
        "real_implementation_percent": None,
        "next_allowed_gate": gate_label + "_HOLD_PENDING_NATIVE_DECISION_REVIEW",
        "blocking_reason_if_any": "NATIVE_REPOSITORY_EVIDENCE_REQUIRES_REVIEW",
        "source_semantic_fields_complete": False,
        "semantic_fields_complete": True,
        "bridge_verdict": "NATIVE_REPOSITORY_EVIDENCE_DERIVED_FAIL_CLOSED",
        "native_decision_evidence": {
            "source": "repository_contract_audit",
            "matched_files": matched_files,
            "scanned_files": scanned_files,
            "matched_paths_sample": sorted(set(matched_paths))[:25],
            "matched_terms_sample": sorted(matched_terms)[:50],
            "reason": "repository evidence is present but does not by itself authorize opening the gate",
        },
    }

def _promote_native_decision_from_semantic_extract(result, check_results):
    semantic_report = None

    for check_result in check_results:
        if (
            check_result.get("type") == "worker_result_semantic_extract"
            and check_result.get("status") == "PASS"
        ):
            semantic_report = _semantic_extract_payload(check_result)
            if semantic_report is not None:
                break

    if semantic_report is None:
        result["blockers"].append(
            "expected_native_decision_requires_worker_result_semantic_extract"
        )
        return

    result["native_decision_evidence"] = semantic_report

    semantic_fields = semantic_report.get("semantic_fields")
    if not isinstance(semantic_fields, dict):
        semantic_fields = {}

    for field in (
        "gate3_allowed",
        "last_gate_executed",
        "last_gate_certified",
        "real_implementation_percent",
        "next_allowed_gate",
        "blocking_reason_if_any",
        "evidence_by_file",
        "evidence_by_module",
    ):
        if field in semantic_fields:
            result[field] = semantic_fields[field]
        elif field in semantic_report:
            result[field] = semantic_report[field]

    if "blockers" in semantic_fields:
        result["native_decision_blockers"] = semantic_fields["blockers"]
    elif "blockers" in semantic_report:
        result["native_decision_blockers"] = semantic_report["blockers"]

    result["semantic_fields"] = dict(semantic_fields)
    result["source_semantic_fields_complete"] = semantic_report.get(
        "source_semantic_fields_complete"
    )
    result["semantic_fields_complete"] = semantic_report.get(
        "semantic_fields_complete"
    )
    result["bridge_verdict"] = semantic_report.get("bridge_verdict")

    if semantic_report.get("source_semantic_fields_complete") is False:
        native_repository_decision = _native_decision_from_repository_contract_audit(result, check_results)
        if native_repository_decision is not None:
            semantic_fields = {
                "gate3_allowed": native_repository_decision.get("gate3_allowed"),
                "last_gate_executed": native_repository_decision.get("last_gate_executed"),
                "last_gate_certified": native_repository_decision.get("last_gate_certified"),
                "real_implementation_percent": native_repository_decision.get("real_implementation_percent"),
                "next_allowed_gate": native_repository_decision.get("next_allowed_gate"),
                "blocking_reason_if_any": native_repository_decision.get("blocking_reason_if_any"),
            }
            result["native_decision_evidence"] = native_repository_decision.get("native_decision_evidence")
            result["semantic_fields"] = dict(semantic_fields)
            for field, value in semantic_fields.items():
                result[field] = value
            result["source_semantic_fields_complete"] = native_repository_decision.get(
                "source_semantic_fields_complete"
            )
            result["semantic_fields_complete"] = native_repository_decision.get(
                "semantic_fields_complete"
            )
