def _load_preferred_job() -> dict[str, Any] | None:
    try:
        payload = json.loads(PREFERRED_JOB_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, TypeError):
        return None
    job_id = str(payload.get("job_id") or "").strip()
    try:
        expires_at = float(payload.get("expires_at_epoch") or 0)
    except (TypeError, ValueError):
        expires_at = 0
    if not JOB_ID_RE.fullmatch(job_id) or expires_at <= datetime.now(timezone.utc).timestamp():
        try:
            PREFERRED_JOB_PATH.unlink()
        except OSError:
            pass
        return None
    return payload


def _select_pending_job(jobs: list[Path]) -> tuple[Path | None, bool]:
    preferred = _load_preferred_job()
    if preferred is not None:
        preferred_id = str(preferred["job_id"])
        for path in jobs:
            if path.stem == preferred_id:
                print(f"UNIVERSAL_DISPATCHER=PREFERRED_JOB_SELECTED JOB_ID={preferred_id}")
                return path, True
        try:
            PREFERRED_JOB_PATH.unlink()
        except OSError:
            pass
        print(f"UNIVERSAL_DISPATCHER=PREFERRED_JOB_STALE_IGNORED JOB_ID={preferred_id}")
    if not jobs:
        return None, False
    return jobs[0], False


def claim_one() -> Path | None:
    with LOCK_FILE.open("a+") as lock:
        try:
            fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            print("UNIVERSAL_DISPATCHER=BUSY")
            return None

        jobs = sorted(PENDING.glob("*.json"))
        selected, is_preferred = _select_pending_job(jobs)

        if selected is None:
            print("UNIVERSAL_DISPATCHER=NO_PENDING_JOBS")
            return None

        processing = PROCESSING / selected.name
        os.replace(selected, processing)

        if is_preferred:
            try:
                PREFERRED_JOB_PATH.unlink()
            except OSError:
                pass

        print(f"UNIVERSAL_DISPATCHER=CLAIMED JOB_ID={selected.stem}")
        return processing


def dispatch() -> int:
    ensure_dirs()
    claimed = claim_one()
    if claimed is None:
        return 0
    return process_one(claimed, already_claimed=True)


def main() -> int:
    return dispatch()


if __name__ == "__main__":
    raise SystemExit(main())

"""Registered semantic capabilities for the remote Worker ingress.

The public semantic boundary never accepts raw Worker actions/checks. Each
capability expands an objective into one deterministic Worker request.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Mapping


class SemanticCapabilityError(ValueError):
    pass


@dataclass(frozen=True)
class SemanticCapability:
    code: str
    modes: tuple[str, ...]
    builder: Callable[[Mapping[str, Any]], dict[str, Any]] | None = None
    submitter: Callable[
        [Mapping[str, Any], Mapping[str, Any]],
        dict[str, Any],
    ] | None = None


_CAPABILITIES: dict[str, SemanticCapability] = {}


def register_capability(capability: SemanticCapability) -> None:
    code = str(capability.code or "").strip().upper()
    if not code:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_CODE_REQUIRED")
    if code in _CAPABILITIES:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_DUPLICATE")
    if not capability.modes:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_MODE_REQUIRED")
    if (capability.builder is None) == (capability.submitter is None):
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_HANDLER_INVALID")
    _CAPABILITIES[code] = capability


def registered_capabilities() -> tuple[str, ...]:
    return tuple(sorted(_CAPABILITIES))


def resolve_capability(code: str) -> SemanticCapability:
    value = str(code or "").strip().upper()
    capability = _CAPABILITIES.get(value)
    if capability is None:
        raise SemanticCapabilityError("SEMANTIC_CAPABILITY_UNKNOWN")
    return capability


def _read_only_canary_builder(request: Mapping[str, Any]) -> dict[str, Any]:
    constraints = request.get("constraints")
    constraints = dict(constraints) if isinstance(constraints, Mapping) else {}
    if constraints:
        unknown = sorted(constraints)
        raise SemanticCapabilityError(
            "SEMANTIC_CONSTRAINTS_UNSUPPORTED:" + ",".join(unknown)
        )

    bounded_context = str(request.get("bounded_context") or "").strip().upper()
    return {
        "actions": [],
        "checks": [{"type": "git_diff_check"}],
        "scheduling": {
            "project_id": "EDARSAHUB",
            "bounded_context": bounded_context,
            "priority_class": "NORMAL",
            "fairness_weight": 1,
            "max_parallelism": 1,
            "resource_claims": [],
            "conflict_domains": [bounded_context],
        },
    }


register_capability(
    SemanticCapability(
        code="READ_ONLY_CANARY",
        modes=("READ_ONLY",),
        builder=_read_only_canary_builder,
    )
)

